def fitness_function(tree, X, y):
    """Evaluate fitness of a candidate program. Lower is better."""
    y_pred = safe_evaluate(tree, X)
    return float(np.mean((y - y_pred) ** 2))


def selection(population, fitnesses, n_select, tournament_size=7):
    """Tournament selection on penalized fitnesses."""
    selected = []
    pop_size = len(population)
    for _ in range(n_select):
        candidates = random.sample(range(pop_size), min(tournament_size, pop_size))
        best = min(candidates, key=lambda i: fitnesses[i])
        selected.append(population[best].copy())
    return selected


def crossover(parent1, parent2, n_features, max_depth=17):
    """Standard subtree crossover."""
    offspring = parent1.copy()
    donor = parent2.copy()
    off_size = offspring.size()
    don_size = donor.size()
    if off_size <= 1 or don_size <= 1:
        return offspring

    off_point = random.randint(1, off_size - 1)
    don_point = random.randint(0, don_size - 1)

    donor_nodes = donor.get_all_nodes()
    donor_subtree = donor_nodes[don_point][0].copy()

    off_nodes = offspring.get_all_nodes()
    node, parent, child_idx = off_nodes[off_point]
    if parent is not None:
        parent.children[child_idx] = donor_subtree
    else:
        offspring = donor_subtree

    if offspring.depth() > max_depth:
        return parent1.copy()
    return offspring


def mutate_subtree(parent, n_features, max_depth):
    offspring = parent.copy()
    tree_size = offspring.size()
    if tree_size <= 1:
        return generate_tree('grow', 3, n_features)
    mut_point = random.randint(1, tree_size - 1)
    new_subtree = generate_tree('grow', 3, n_features)
    nodes = offspring.get_all_nodes()
    node, par, child_idx = nodes[mut_point]
    if par is not None:
        par.children[child_idx] = new_subtree
    else:
        offspring = new_subtree
    if offspring.depth() > max_depth:
        return parent.copy()
    return offspring


def mutate_point(parent, n_features, max_depth):
    offspring = parent.copy()
    nodes = offspring.get_all_nodes()
    for node, _, _ in nodes:
        if random.random() < 0.1:
            if node.is_terminal:
                if random.random() < 0.5:
                    node.value = f'x{random.randint(0, n_features - 1)}'
                else:
                    node.value = str(round(random.uniform(-5.0, 5.0), 2))
            else:
                arity = len(node.children)
                valid_ops = [op for op, n_args in OPERATORS.items() if n_args == arity]
                if valid_ops:
                    node.value = random.choice(valid_ops)
    return offspring


def mutate_hoist(parent, n_features, max_depth):
    offspring = parent.copy()
    nodes = offspring.get_all_nodes()
    if len(nodes) <= 1:
        return offspring
    mut_point = random.randint(1, len(nodes) - 1)
    node, par, child_idx = nodes[mut_point]

    sub_nodes = node.get_all_nodes()
    if len(sub_nodes) <= 1:
        return offspring
    sub_mut_point = random.randint(1, len(sub_nodes) - 1)
    new_subtree = sub_nodes[sub_mut_point][0].copy()

    if par is not None:
        par.children[child_idx] = new_subtree
    else:
        offspring = new_subtree
    return offspring


def mutate_collapse(parent, n_features, max_depth):
    offspring = parent.copy()
    nodes = offspring.get_all_nodes()
    if len(nodes) <= 1:
        return offspring
    mut_point = random.randint(1, len(nodes) - 1)
    node, par, child_idx = nodes[mut_point]

    if par is not None:
        par.children[child_idx] = random_terminal(n_features)
    else:
        offspring = random_terminal(n_features)
    return offspring


def mutate_constants(parent, n_features, max_depth):
    offspring = parent.copy()
    nodes = offspring.get_all_nodes()
    for node, _, _ in nodes:
        if node.is_terminal and isinstance(node.value, str) and not node.value.startswith('x'):
            try:
                val = float(node.value)
                val += random.gauss(0, 0.5)
                node.value = str(round(val, 4))
            except ValueError:
                pass
    return offspring


def mutation(parent, n_features, max_depth=17):
    """Randomly apply one of several mutation strategies."""
    r = random.random()
    if r < 0.3:
        return mutate_subtree(parent, n_features, max_depth)
    elif r < 0.5:
        return mutate_point(parent, n_features, max_depth)
    elif r < 0.7:
        return mutate_hoist(parent, n_features, max_depth)
    elif r < 0.8:
        return mutate_collapse(parent, n_features, max_depth)
    else:
        return mutate_constants(parent, n_features, max_depth)


def evolve_one_generation(population, fitnesses, X_train, y_train,
                          n_features, pop_size,
                          crossover_rate=0.9, mutation_rate=0.05,
                          max_depth=17):
    """Evolution step with adaptive parsimony, multiple mutators, and random immigrants."""
    new_population = []

    lengths = np.array([tree.size() for tree in population], dtype=float)
    raw_fit = np.array(fitnesses, dtype=float)
    len_var = float(np.var(lengths))
    if len_var > 1e-15:
        parsimony_coeff = float(np.cov(lengths, raw_fit)[1, 0]) / len_var
        parsimony_coeff = max(parsimony_coeff, 0.0)
        parsimony_coeff = min(parsimony_coeff, 0.005)
    else:
        parsimony_coeff = 0.0

    penalized = [f + parsimony_coeff * l for f, l in zip(fitnesses, lengths)]

    # Elitism
    sorted_indices = np.argsort(fitnesses)
    elite_count = max(1, pop_size // 100)
    for i in range(elite_count):
        new_population.append(population[sorted_indices[i]].copy())

    # Immigrants
    n_random = max(1, pop_size // 50)
    for _ in range(n_random):
        depth = random.randint(2, max_depth - 2) if max_depth > 4 else 3
        new_population.append(generate_tree('grow', depth, n_features))

    crossover_p = 0.6
    mutation_p = 0.4

    while len(new_population) < pop_size:
        r = random.random()
        if r < crossover_p:
            parents = selection(population, penalized, 2)
            child = crossover(parents[0], parents[1], n_features, max_depth)
        elif r < crossover_p + mutation_p:
            parents = selection(population, penalized, 1)
            child = mutation(parents[0], n_features, max_depth)
        else:
            parents = selection(population, penalized, 1)
            child = parents[0]
        new_population.append(child)

    return new_population[:pop_size]

